#!/usr/bin/env node
// Deterministic resume linter: the machine-checkable rules from career-ops' modes/_custom.md, as code.
// Reads the .tex (hand-edited or generated by build-cv-latex with cv-template.bao) and, when present, the PDF.
//
// Each resume declares its angle above \begin{document}, or in tailoring-data.json beside it ("narrative", "terms"),
// since the builder can't write comments:
//   % narrative: <one sentence: what this resume argues for this JD>
//   % terms: <comma-separated JD terms the narrative rests on, e.g. agents, evaluation, GCP>
// Terms gate filler libraries and certification order; entries are not required to use them (user, 2026-11-23).
// Contact details (email, LinkedIn, GitHub) come from career-ops' config/profile.yml, not this file.
//
// Usage: node scripts/resume-schema.mjs [file.tex ...] [--pdf=<compiled.pdf>]   (default: every output/*/ resume except the master)
// Edge cases: npm test   (scripts/resume-schema.test.mjs)
// Enforced in code, not by any editor or agent: career-ops' generate-latex.mjs refuses to compile an output/ resume that
// fails (and deletes a PDF that fails the page checks), and scripts/build-resume.sh refuses to publish one.
// Lives in personal-website (synced by git across machines). Exempt: the 2-page master pool.
import { readFileSync, existsSync, readdirSync, statSync, realpathSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { join, resolve, dirname } from 'node:path';
import { pathToFileURL } from 'node:url';

const ROOT = resolve(import.meta.dirname, '../../career-ops'); // resumes live in career-ops/output
const MASTER = join(ROOT, 'output', '_general', 'Resume - Bao Nguyen.tex');
const PROFILE = process.env.CAREER_OPS_PROFILE || join(ROOT, 'config', 'profile.yml');
// _custom.md "Resume Section Order"; nothing else may appear.
const SECTIONS = [['Experience', /experience/i], ['Projects', /projects/i], ['Certifications', /certifications/i], ['Technical Skills', /skills/i], ['Education', /education/i]];
const SKILL_CATEGORIES = ['Languages', 'Developer Tools', 'Libraries'];
const FILLER_LIBS = ['scikit-learn', 'sklearn', 'lora', 'sentence-transformers', 'psycopg2']; // allowed only when a declared term names them
// _custom.md "Skills Category Boundaries" (cv.md is the source; these are the ones it has settled).
const SKILL_HOME = { python: 'Languages', r: 'Languages', sql: 'Languages',
  fastapi: 'Libraries', pgvector: 'Libraries', langchain: 'Libraries', langsmith: 'Libraries', langgraph: 'Libraries', mcp: 'Libraries', pytorch: 'Libraries', tensorflow: 'Libraries', postgresql: 'Libraries', pytest: 'Libraries',
  codex: 'Developer Tools', git: 'Developer Tools', linux: 'Developer Tools', aws: 'Developer Tools', gcp: 'Developer Tools', azure: 'Developer Tools' };
const TABLE_STAKES = new Set(['llm', 'llms', 'ai', 'ml', 'api', 'apis', 'data', 'cloud', 'agent', 'agents', 'agentic']);
const SOFT_BOLD = /^(built|designed|shipped|production-grade|end-to-end|scalable|robust|state-of-the-art|cutting-edge|innovative)$/i;
// ponytail: past-tense heuristic for "never bold verbs"; a real POS tagger if it misfires.
const VERB = (w) => /^[a-z]{3,}ed$/i.test(w) && !/eed$/i.test(w);
const BANNED_PROJECTS = /\bmarrow\b|stat\s*471/i;
// ponytail: known technique/operational words that don't belong in a project stack; extend when a new one slips in.
const STACK_TECHNIQUES = /worktree|\bhooks?\b|filtering|reranking|diagnostics|fine-tuning|retrieval|\bRAG\b|regression/i;
const STACK_POSTURE = /standard library|stdlib|zero[- ]dependenc|no dependenc|dependency-free/i;
const AWS_TERMS = /\b(aws|sagemaker|bedrock|ec2|s3)\b/i, GCP_TERMS = /\b(gcp|google cloud|vertex ai|bigquery)\b/i;
const CERTS = [['GCP', 'GCP Professional Machine Learning Engineer', 'May 2026'], ['AWS', 'AWS Certified Machine Learning Engineer', 'Sep 2025']];
const DATE = /\b(19|20)\d\d\b|Present/;
// Macros that may legitimately contain \item; any other macro wrapping a bullet hides it from the count.
const KNOWN_MACROS = new Set(['resumeItem', 'resumeSubItem', 'resumeSubheading', 'resumeSubheadingContinue', 'resumeProjectHeading', 'resumeSubHeadingListStart', 'resumeSubHeadingListEnd', 'resumeItemListStart', 'resumeItemListEnd']);

// candidate.{email,linkedin,github} from profile.yml. ponytail: line regex, not a YAML parser; flat scalar fields only.
let contactCache;
function contact() {
  if (contactCache !== undefined) return contactCache;
  if (!existsSync(PROFILE)) return (contactCache = null);
  const y = readFileSync(PROFILE, 'utf8'), get = (k) => y.match(new RegExp(`^\\s+${k}:\\s*["']?([^"'#\\n]+?)["']?\\s*(#.*)?$`, 'm'))?.[1];
  const handle = (v, host) => v?.replace(/^https?:\/\//, '').replace(/^www\./, '').replace(new RegExp(`^${host}/`), '').replace(/\/$/, '');
  return (contactCache = { email: get('email'), linkedin: handle(get('linkedin'), 'linkedin\\.com'), github: handle(get('github'), 'github\\.com') });
}
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// ---------- parsing ----------
function braceArg(s, i) { // s[i] must be '{'; returns [content, indexAfterClosingBrace]
  let depth = 0;
  for (let j = i; j < s.length; j++) {
    if (s[j] === '\\') { j++; continue; }
    if (s[j] === '{') depth++;
    else if (s[j] === '}' && --depth === 0) return [s.slice(i + 1, j), j + 1];
  }
  return [s.slice(i + 1), s.length];
}
function readArgs(s, i, n) {
  const out = [];
  while (out.length < n) {
    while (i < s.length && /\s/.test(s[i])) i++;
    if (s[i] !== '{') break;
    const [a, next] = braceArg(s, i); out.push(a); i = next;
  }
  return out;
}
export const plain = (t = '') => String(t)
  .replace(/\\href\{[^}]*\}/g, '').replace(/\$\\tau\$/g, 'τ').replace(/\\%/g, '%').replace(/\\&/g, '&')
  .replace(/\\[a-zA-Z]+\*?/g, '').replace(/[{}$]/g, '').replace(/\s+/g, ' ').trim();
const blank = (s) => s.replace(/[^\n]/g, ' '); // keep offsets and line numbers

// Every \newcommand/\renewcommand/\def: [name, body, start, end].
function macroDefs(s) {
  const out = [];
  for (const m of s.matchAll(/\\(?:re)?newcommand\*?\s*\{?\\([a-zA-Z]+)\}?\s*(?:\[\d\])?\s*(?:\[[^\]]*\])?\s*(?=\{)|\\def\s*\\([a-zA-Z]+)[^{]*(?=\{)/g)) {
    const [body, end] = braceArg(s, m.index + m[0].length);
    out.push([m[1] ?? m[2], body, m.index, end]);
  }
  return out;
}
const ARITY = { section: 1, 'section*': 1, resumeSubheading: 4, resumeSubheadingContinue: 2, resumeProjectHeading: 2, resumeItem: 1, resumeSubItem: 1, item: 0 };

export function parse(src, declared = {}) {
  const [preamble, rawBody = ''] = src.split('\\begin{document}');
  const uncommented = rawBody.replace(/(?<!\\)%.*$/gm, ''); // drop LaTeX comments
  let body = uncommented.replace(/\\iffalse\b[\s\S]*?\\fi\b/g, blank).replace(/\\begin\{comment\}[\s\S]*?\\end\{comment\}/g, blank);
  for (const [, , a, b] of macroDefs(body).reverse()) body = body.slice(0, a) + blank(body.slice(a, b)) + body.slice(b); // a definition is not an entry
  const meta = (k) => preamble.match(new RegExp(`^%\\s*${k}:\\s*(\\S.*)$`, 'mi'))?.[1].trim();
  const sections = [];
  let sec = null, entry = null;
  for (const m of body.matchAll(/\\(section\*?|resumeSubheadingContinue|resumeSubheading|resumeProjectHeading|resumeSubItem|resumeItem|item)(?![a-zA-Z])/g)) {
    const args = readArgs(body, m.index + m[0].length, ARITY[m[1]]);
    if (m[1].startsWith('section')) { sec = { name: plain(args[0] ?? ''), start: m.index, entries: [] }; sections.push(sec); entry = null; }
    else if (m[1] === 'resumeItem' || m[1] === 'resumeSubItem') { if (entry) entry.bullets.push(args[0] ?? ''); }
    else if (m[1] === 'item') { if (entry) entry.bullets.push(body.slice(m.index + 5).split(/\\(?:item(?![a-zA-Z])|resume|end|section)/)[0]); } // a hand-written bullet counts too
    else if (sec) { entry = { kind: m[1], args, bullets: [] }; sec.entries.push(entry); }
  }
  // Section text keeps macro definitions: the generated template's per-section \renewcommands tell us its layout.
  sections.forEach((s, i) => { s.text = uncommented.slice(s.start, sections[i + 1]?.start ?? body.length); });
  const termsRaw = meta('terms') ?? (Array.isArray(declared.terms) ? declared.terms.join(',') : declared.terms ?? '');
  return { preamble, rawBody, body, narrative: meta('narrative') ?? declared.narrative, terms: termsRaw.split(',').map((t) => t.trim()).filter(Boolean),
    sections, wrappers: macroDefs(src).filter(([name, def]) => !KNOWN_MACROS.has(name) && /\\resumeItem|\\item(?![a-zA-Z])/.test(def)).map(([name]) => name) };
}
const label = (e) => plain(e.args[0] ?? '').split('|')[0].trim() || '?';
const sectionOf = (r, re) => r.sections.filter((s) => re.test(s.name));
const roleEntries = (r) => r.sections.filter((s) => /experience|projects/i.test(s.name)).flatMap((s) => s.entries.map((e) => ({ ...e, section: s.name })));
const boldSpans = (b) => [
  ...[...b.matchAll(/\\textbf(?=\{)/g)].map((m) => braceArg(b, m.index + 7)[0]),
  ...[...b.matchAll(/\{\\bf(?:series)?\s+([^}]*)\}/g)].map((m) => m[1]),
].map(plain);
function skillLines(s) { // [[category, rawValue]] for \textbf{Cat}{: items} and \textbf{Cat}{: }{items}
  return [...s.text.matchAll(/\\textbf(?=\{)/g)].map((m) => {
    const [cat, i] = braceArg(s.text, m.index + 7), [a0 = '', a1 = ''] = readArgs(s.text, i, 2);
    return [plain(cat), plain(a0) === ':' ? a1 : a0.replace(/^\s*:\s*/, '')];
  }).filter(([, v]) => v);
}

// ---------- rules (each returns a list of error strings) ----------
const RULES = {
  narrative(r) {
    const errs = [];
    if (!r.narrative) errs.push('missing `% narrative: <one sentence>` above \\begin{document} (or "narrative" in tailoring-data.json)');
    else if (/[.!?]\s+\S/.test(r.narrative)) errs.push('narrative must be one sentence');
    if (!r.terms.length) errs.push('missing `% terms: a, b, c` above \\begin{document} (or "terms" in tailoring-data.json)');
    return errs;
  },
  bulletCount(r) {
    const errs = r.wrappers.map((n) => `custom macro \\${n} wraps a bullet, so it can't be counted; use \\resumeItem`);
    const entries = roleEntries(r);
    if (!entries.length) return [...errs, 'no Experience/Projects entries found'];
    // Projects cap at 3 so the page's space goes to Experience.
    return [...errs, ...entries.flatMap((e) => {
      const max = /projects/i.test(e.section) ? 3 : 4, n = e.bullets.length;
      return n < 2 || n > max ? [`${label(e)}: ${n} bullets (need 2-${max})`] : [];
    })];
  },
  bulletStyle(r) {
    const errs = [];
    for (const e of roleEntries(r)) for (const b of e.bullets) {
      const raw = b.replace(/\\href\{[^}]*\}/g, ''), t = plain(b), short = `${label(e)}: "${t.slice(0, 50)}…"`;
      if (/~|\\sim\b|\\textasciitilde/.test(raw)) errs.push(`${short} uses ~ (write "about")`);
      if (/\s\+\s|[a-z0-9]\+[a-z]/i.test(t)) errs.push(`${short} uses + as "and"`);
      if (/\s&\s/.test(t)) errs.push(`${short} uses & as "and"`);
      if (/\\(?:long)?[rR]ightarrow\b|\\to\b|->|=>|→|⇒/.test(raw)) errs.push(`${short} uses an arrow (write it as a sentence)`);
      if (/\bw\/\s/i.test(t)) errs.push(`${short} uses w/ (write "with")`);
      if (/:\s/.test(t)) errs.push(`${short} has a colon clause list`);
      if ((t.match(/\(/g) ?? []).length > 1) errs.push(`${short} stacks parentheticals`);
      if (/\b(we|our|ours|ourselves)\b/i.test(t) || /\bus\b/.test(t)) errs.push(`${short} uses we/our`);
    }
    return errs;
  },
  bolding(r) {
    const errs = [], seen = new Set();
    for (const s of r.sections) for (const e of s.entries) for (const b of e.bullets) {
      const bolds = boldSpans(b);
      if (bolds.length > 3) errs.push(`${label(e)}: ${bolds.length} bold spans in one bullet (max 3)`);
      for (const w of bolds) {
        const words = w.toLowerCase().split(/\s+/).filter(Boolean);
        if (words.every((x) => TABLE_STAKES.has(x))) errs.push(`${label(e)}: never bold a term every applicant has ("${w}")`);
        else if (words.some((x) => SOFT_BOLD.test(x)) || VERB(words[0] ?? '')) errs.push(`${label(e)}: never bold verbs or soft claims ("${w}")`);
        if (words.length > 4) errs.push(`${label(e)}: bold covers a whole clause ("${w.slice(0, 40)}"); bold the number or the named technology`);
        if (!/^[\d.,%\s]+$/.test(w) && seen.has(w.toLowerCase())) errs.push(`${label(e)}: "${w}" bolded again (first occurrence only)`);
        seen.add(w.toLowerCase());
      }
    }
    return errs;
  },
  sections(r) {
    const errs = [], names = r.sections.map((s) => s.name), summary = /summary|profile|objective|about/i;
    if (names.some((n) => summary.test(n))) errs.push('has a summary section (not allowed)');
    const ids = names.map((n) => SECTIONS.findIndex(([, re]) => re.test(n)));
    names.forEach((n, i) => { if (ids[i] < 0 && !summary.test(n)) errs.push(`unexpected section "${n}"`); });
    SECTIONS.forEach(([name], k) => {
      const c = ids.filter((x) => x === k).length;
      if (c !== 1) errs.push(c ? `${name} appears ${c} times` : `missing ${name} section`);
    });
    const known = ids.filter((x) => x >= 0);
    if (known.some((v, i) => i && v < known[i - 1])) errs.push(`section order is ${names.join(' > ')}; need ${SECTIONS.map(([n]) => n).join(' > ')}`);
    return errs;
  },
  header(r) {
    const errs = [], head = r.body.slice(0, r.sections[0]?.start ?? 0), shown = plain(head), c = contact();
    if (!/Edmonton, AB\s*(\||\\\\|$)/.test(shown) || /Canada|Remote|Hybrid|relocat|Alberta|UTC|GMT|\b[A-Z][SD]?T\b/.test(shown)) errs.push('header location must be exactly "Edmonton, AB" (no country, remote status, or timezone)');
    if (!c?.email || !c.linkedin || !c.github) return [...errs, `can't check contact details: no candidate email/linkedin/github in ${PROFILE}`];
    const mailto = [...head.matchAll(/mailto:([^}]+)/g)].map((m) => m[1]);
    if (mailto.length !== 1 || mailto[0] !== c.email) errs.push(`email link must be mailto: the profile.yml email (found ${mailto.map((m) => `mailto:${m}`).join(', ') || 'none'})`);
    const visible = shown.match(/[\w.+-]+@[\w.-]+/g) ?? [];
    if (visible.length !== 1 || visible[0] !== c.email) errs.push(`shown email must be the profile.yml email (found ${visible.join(', ') || 'none'})`);
    // User preference (2026-11-23): logo + word, linked, instead of the written-out URL.
    if (!new RegExp(`\\\\href\\{https://(www\\.)?linkedin\\.com/${esc(c.linkedin)}/?\\}`).test(head) || !/\\faLinkedin/.test(head) || !/\bLinkedIn\b/.test(shown)) errs.push(`header needs \\faLinkedin LinkedIn linked to linkedin.com/${c.linkedin}`);
    if (!new RegExp(`\\\\href\\{https://github\\.com/${esc(c.github)}/?\\}`).test(head) || !/\\faGithub/.test(head) || !/\bGitHub\b/.test(shown)) errs.push(`header needs \\faGithub GitHub linked to github.com/${c.github}`);
    if (/linkedin\.com|github\.com/i.test(shown)) errs.push('header shows a full URL; show the logo and the word instead');
    return errs;
  },
  experience(r) {
    const errs = [];
    for (const s of sectionOf(r, /experience/i)) {
      // cv-template.bao swaps #2/#4 inside the section: builder passes {company}{dates}{role}{location}.
      const swapped = /\\renewcommand\{\\resumeSubheading\}[\s\S]*?\\textbf\{\\small #4\}/.test(s.text);
      let prev = null;
      s.entries.forEach((e, i) => {
        if (e.kind === 'resumeSubheadingContinue') { if (!i) errs.push(`${plain(e.args[0])}: continuation line with no company above it`); return; }
        if (e.kind !== 'resumeSubheading') return;
        const company = plain(e.args[0]).toLowerCase().replace(/[^a-z0-9]/g, ''), loc = plain(e.args[swapped ? 3 : 1]), date = plain(e.args[swapped ? 1 : 3]);
        if (prev === company) errs.push(`${plain(e.args[0])} repeated; use \\resumeSubheadingContinue`);
        prev = company;
        if (!DATE.test(date) || DATE.test(loc)) errs.push(`${plain(e.args[0])}: location goes on line 1 and dates on line 2`);
        else if (company === 'm2mtech' && loc !== 'Vancouver, BC') errs.push(`M2M Tech location is "${loc}"; must be "Vancouver, BC"`);
      });
    }
    return errs;
  },
  projects(r) {
    const errs = [];
    for (const s of sectionOf(r, /projects/i)) {
      // Generated (cv-template.bao): \href{gh}{\textbf{name}} \emph{$|$ stack}; the section redefines \href to underline
      // and drops the heading macro's blanket bold. Hand-edited: \href{gh}{\underline{name}} \textnormal{$|$ \emph{stack}}.
      const hrefUnderlines = /\\renewcommand\{\\href\}[\s\S]*?\\underline/.test(s.text);
      const headingUnbolded = /\\renewcommand\{\\resumeProjectHeading\}\[2\]\{[\s\S]*?\n\s*#1 &/.test(s.text);
      for (const e of s.entries) {
        const [name = '', date = ''] = e.args, parts = plain(name).split('|').map((p) => p.trim());
        if (plain(date)) errs.push(`${label(e)}: project header has a date`);
        if (!/\\href\{https:\/\/github\.com\/[^/}]+\/[^/}]+\/?\}/.test(name)) errs.push(`${label(e)}: name must link to its GitHub repo (github.com/owner/repo)`);
        if (!/\\underline\{/.test(name) && !hrefUnderlines) errs.push(`${label(e)}: name must be underlined`);
        if (!/\\textnormal\{\$\|\$ \\emph\{/.test(name) && !(headingUnbolded && /\\emph\{\$\|\$/.test(name))) errs.push(`${label(e)}: stack must be italic and not bold, as \\textnormal{$|$ \\emph{stack}}`);
        if (parts.length > 2) errs.push(`${label(e)}: header shows something besides the stack ("${parts.slice(2).join(' | ')}")`);
        const stack = parts[1] ?? '', items = stack.split(',').map((x) => x.trim().toLowerCase());
        for (const lib of FILLER_LIBS) if (lib !== 'psycopg2' && items.includes(lib)) errs.push(`${label(e)}: stack lists filler ${lib}`);
        if (STACK_POSTURE.test(stack)) errs.push(`${label(e)}: stack states a dependency posture; say it in a bullet`);
        if (STACK_TECHNIQUES.test(stack)) errs.push(`${label(e)}: stack lists a technique, not a package ("${stack}")`);
      }
    }
    return errs;
  },
  skills(r) {
    const s = sectionOf(r, /skills/i)[0];
    if (!s) return ['no Technical Skills section'];
    const errs = [], lines = skillLines(s);
    if (lines.map((c) => c[0]).join('|') !== SKILL_CATEGORIES.join('|')) errs.push(`skills categories are [${lines.map((c) => c[0])}]; need exactly ${SKILL_CATEGORIES.join(', ')}`);
    const seen = new Set();
    for (const [cat, raw] of lines) {
      if (/\\textbf|\\bf\b/.test(raw)) errs.push(`${cat}: skills lines stay unbolded`);
      for (const item of plain(raw).split(',').map((x) => x.trim()).filter(Boolean)) {
        const k = item.toLowerCase();
        if (seen.has(k)) errs.push(`${item} listed twice`);
        seen.add(k);
        if (SKILL_CATEGORIES.includes(cat) && SKILL_HOME[k] && SKILL_HOME[k] !== cat) errs.push(`${item} belongs in ${SKILL_HOME[k]}, not ${cat} (cv.md)`);
        if (cat === 'Libraries' && FILLER_LIBS.includes(k) && !r.terms.some((t) => t.toLowerCase() === k)) errs.push(`Libraries lists ${item} but no declared term names it`);
        if (k === 'latex') errs.push('LaTeX is never listed as a skill (user rule, 2026-11-23)');
      }
    }
    const tools = lines.find((c) => c[0] === 'Developer Tools')?.[1] ?? '';
    for (const cloud of ['AWS', 'GCP', 'Azure']) if (!new RegExp(`\\b${cloud}\\b`, 'i').test(tools)) errs.push(`Developer Tools missing ${cloud}`);
    return errs;
  },
  certifications(r) {
    const s = sectionOf(r, /certifications/i)[0];
    if (!s) return ['no Certifications section'];
    const errs = [], bolds2 = /\\textbf\{(\\small\s*)?#2\}/.test(s.text);
    // Generated: \resumeProjectHeading{\textbf{name}}{date} with a macro that bolds #2. Hand: \textbf{name} & \textbf{date} \\
    const certs = s.entries.length
      ? s.entries.map((e) => ({ name: e.args[0] ?? '', date: e.args[1] ?? '', dateBold: bolds2 }))
      : [...s.text.matchAll(/([^\n&]*)&([^\n]*?)\\\\/g)].filter((m) => /\d{4}/.test(m[2])).map((m) => ({ name: m[1], date: m[2], dateBold: /\\textbf\{/.test(m[2]) }));
    if (/azure|microsoft/i.test(plain(s.text))) errs.push('no Azure certification exists; never list one');
    if (certs.length !== 2) errs.push(`Certifications lists ${certs.length} entries; need exactly the GCP and AWS ML Engineer certifications`);
    const pos = Object.fromEntries(CERTS.map(([id, title, when]) => {
      const i = certs.findIndex((c) => plain(c.name).includes(title));
      if (i < 0) errs.push(`Certifications missing ${title}`);
      else if (plain(certs[i].date) !== when) errs.push(`${id} certification date is "${plain(certs[i].date)}"; must be "${when}"`);
      return [id, i];
    }));
    for (const c of certs) {
      if (!/\\textbf\{/.test(c.name)) errs.push(`certification name not bold: ${plain(c.name)}`);
      if (!c.dateBold) errs.push(`certification date not bold: ${plain(c.date)}`);
    }
    const terms = r.terms.join(' '), awsFirst = AWS_TERMS.test(terms) && !GCP_TERMS.test(terms);
    if (pos.GCP >= 0 && pos.AWS >= 0 && awsFirst !== pos.AWS < pos.GCP) errs.push(`Certifications should lead with ${awsFirst ? 'AWS' : 'GCP'} for the declared terms`);
    return errs;
  },
  content(r) {
    const errs = [], head = r.body.slice(0, r.sections[0]?.start ?? 0);
    if (/(?<!NVIDIA )NeMo/.test(plain(r.body))) errs.push('write "NVIDIA NeMo", never "NeMo" alone');
    if (BANNED_PROJECTS.test(r.body)) errs.push('mentions marrow or STAT 471 (held back until approved)');
    if (/\\begin\{(multicols|paracol)\}|\\twocolumn\b/.test(r.body) || /\\documentclass\[[^\]]*twocolumn/.test(r.preamble)) errs.push('uses columns (breaks ATS)');
    if (/\\includegraphics/.test(r.body)) errs.push('uses images (break ATS)');
    // Logos only as the LinkedIn/GitHub link decorations in the contact header.
    for (const m of r.body.matchAll(/\\fa[A-Z][a-zA-Z]*/g)) if (m.index >= head.length || !/^\\fa(Linkedin|Github)$/.test(m[0])) errs.push(`icon ${m[0]} not allowed (only \\faLinkedin and \\faGithub in the header)`);
    // Markdown that reached the .tex prints literally: **bold**, [name](url), `code`.
    if (/\*\*[^*\n]+\*\*|(?<![\\$*])\*[A-Za-z][^*\n]*\*(?!\*)|\[[^\]\n]+\]\(https?:[^)\s]+\)|`[^`\n]+`/.test(r.body)) errs.push('Markdown left in the LaTeX (**bold**, *italic*, [name](url) or `code`) prints literally; use \\textbf / \\href');
    if (/\\(input|include)\{/.test(r.body)) errs.push('\\input/\\include pulls in text the checker can\'t see; inline it');
    const edu = sectionOf(r, /education/i).flatMap((s) => s.entries);
    const ua = edu.find((e) => /Alberta/.test(e.args[0] ?? ''));
    if (edu.length && !ua) errs.push('Education must name the University of Alberta');
    for (const e of edu) if (/expected/i.test(e.args[3] ?? '')) errs.push('education date says "Expected"');
    if (ua && plain(ua.args[3] ?? '') !== 'Graduated June 2026') errs.push(`UAlberta date is "${plain(ua.args[3] ?? '')}"; must be "Graduated June 2026"`);
    return errs;
  },
};

// PDF checks: fresh, one page, every bullet within 2 rendered lines.
export function pdfErrors(texPath, pdf = texPath.replace(/\.tex$/, '.pdf')) {
  if (!existsSync(pdf)) return [];
  if (statSync(pdf).mtimeMs < statSync(texPath).mtimeMs) return ['PDF is older than the .tex; recompile before checking'];
  const errs = [];
  try {
    const pages = Number(execFileSync('pdfinfo', [pdf], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).match(/^Pages:\s*(\d+)/m)?.[1]);
    if (pages !== 1) errs.push(`compiled PDF is ${pages} pages (need 1)`);
    errs.push(...renderedLineErrors(execFileSync('pdftotext', ['-layout', pdf, '-'], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] })));
    errs.push(...flushLineErrors(execFileSync('pdftotext', ['-bbox-layout', pdf, '-'], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] })));
  } catch (e) { errs.push(`could not read PDF (${e.message.split('\n')[0]}); install poppler-utils`); }
  return errs;
}
export function renderedLineErrors(text) {
  const errs = [], lines = text.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(/^(\s*)•\s*(.*)$/);
    if (!m) continue;
    let n = 1;
    for (let j = i + 1; j < lines.length; j++) {
      if (!lines[j].trim()) continue;
      const indent = lines[j].match(/^\s*/)[0].length;
      if (lines[j].includes('•') || indent <= m[1].length) break;
      n++;
    }
    if (n > 2) errs.push(`bullet wraps to ${n} lines (max 2): "${m[2].slice(0, 50)}…"`);
  }
  return errs;
}

// _custom.md: a bullet's last line must never run flush to the right margin (\resumeItem's \vspace{-3pt} then breaks
// onto its own line and leaves a gap). From pdftotext -bbox-layout: the margin is the widest line on the page; bullet
// lines start at the bullet indent, continuation lines a little further right.
// ponytail: geometry by tolerance (FLUSH_PT); re-tune if the template's margins or font size change.
const FLUSH_PT = 3;
export function flushLineErrors(xml) {
  const lines = [...xml.matchAll(/<line xMin="([\d.]+)" yMin="([\d.]+)" xMax="([\d.]+)"[^>]*>([\s\S]*?)<\/line>/g)]
    .map((m) => ({ x0: +m[1], y: +m[2], x1: +m[3], text: [...m[4].matchAll(/>([^<]+)<\/word>/g)].map((w) => w[1]).join(' ') }));
  if (!lines.length) return [];
  const margin = Math.max(...lines.map((l) => l.x1));
  const dots = lines.filter((l) => l.text === '•');
  const bulletX = Math.min(...lines.filter((l) => l.text.startsWith('•')).map((l) => l.x0));
  if (!Number.isFinite(bulletX)) return [];
  const body = lines.filter((l) => l.text !== '•' && l.x0 >= bulletX - 1 && l.x0 <= bulletX + 20).sort((a, b) => a.y - b.y);
  const starts = (l) => l.text.startsWith('•') || dots.some((d) => Math.abs(d.y - l.y) < 4);
  const errs = [];
  body.forEach((l, i) => {
    const next = body[i + 1];
    const last = !next || starts(next) || next.y - l.y > 20;
    if (last && l.x1 >= margin - FLUSH_PT) errs.push(`bullet's last line runs flush to the right margin (leaves a gap below it); trim a few words: "${l.text.replace(/^• /, '').slice(0, 50)}…"`);
  });
  return errs;
}

export function lint(src, declared) {
  const r = parse(src, declared);
  // An unescaped % comments out the rest of its line, swallowing closing braces; everything after it parses as noise.
  const pct = r.rawBody.split('\n').filter((l) => /[A-Za-z0-9.)](?<!\\)%(?![0-9A-F]{2})/.test(l));
  if (pct.length) return { narrative: r.narrative, errors: pct.map((l) => `[content] unescaped % (LaTeX drops the rest of the line; write \\%): "${l.trim().slice(0, 60)}"`) };
  return { narrative: r.narrative, errors: Object.entries(RULES).flatMap(([id, fn]) => fn(r).map((e) => `[${id}] ${e}`)) };
}
// A generated resume can't carry comments, so its narrative/terms may live in tailoring-data.json beside it.
export function lintFile(texPath, src = readFileSync(texPath, 'utf8')) {
  const json = join(dirname(texPath), 'tailoring-data.json');
  let declared = {};
  try { if (existsSync(json)) { const d = JSON.parse(readFileSync(json, 'utf8')); declared = { narrative: d.narrative, terms: d.terms }; } } catch { /* bad JSON: the .tex must declare them */ }
  return lint(src, declared);
}

function defaultFiles() {
  const out = join(ROOT, 'output');
  return readdirSync(out).filter((d) => d !== '_archive').flatMap((d) => {
    const dir = join(out, d);
    if (!statSync(dir).isDirectory()) return [];
    return readdirSync(dir).filter((f) => /resume.*\.tex$/i.test(f)).map((f) => join(dir, f));
  }).filter((f) => f !== MASTER);
}

if (process.argv[1] && import.meta.url === pathToFileURL(realpathSync(process.argv[1])).href) {
  const args = process.argv.slice(2);
  const pdfArg = args.find((a) => a.startsWith('--pdf='))?.slice(6);
  const texArgs = args.filter((a) => !a.startsWith('--'));
  const files = texArgs.length ? texArgs.map((f) => resolve(f)) : defaultFiles();
  let failed = 0;
  for (const f of files) {
    const { narrative, errors } = lintFile(f);
    errors.push(...pdfErrors(f, pdfArg ? resolve(pdfArg) : undefined).map((e) => `[pdf] ${e}`));
    const name = f.replace(ROOT + '/', '');
    if (errors.length) { failed++; console.log(`FAIL ${name}\n${errors.map((e) => `     ${e}`).join('\n')}`); }
    else if (texArgs.length) console.log(`ok   ${name}  (narrative: ${narrative})`);
  }
  console.log(`\n${files.length - failed}/${files.length} resumes pass`);
  process.exit(failed ? 1 : 0);
}
